import fs from "fs";
import path from "path";
import config from "@/config";
import Logger from "@/loaders/logger";
import { AiServerError } from "@/errors";
import { compressImageBuffer } from "../utils/imageCompressor";
import type {
  AiChatInternalPayload,
  AiChatInternalResponse,
  ChatTurn,
  PlanetType,
  AiVisionInternalResponse,
  NormalizedVisionResult,
  NutritionLookupResponse,
  AiReportInternalResponse,
  YoloContext,
} from "@/interfaces";

import { Service } from "typedi";

@Service()
export class AiAdapter {
  private getHeaders(): Record<string, string> {
    return {
      "Content-Type": "application/json",
      "X-Internal-Api-Key": config.ai.apiKey || "",
    };
  }

  private async postJson<T>(
    endpoint: string,
    payload: unknown,
    serviceName: string,
  ): Promise<T> {
    const url = `${config.ai.serverUrl}${endpoint}`;
    const MAX_RETRIES = 3;
    let lastError: unknown;

    for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
      try {
        Logger.info(
          `[AiAdapter] Requesting ${serviceName} via ${endpoint} (Attempt ${attempt}/${MAX_RETRIES})`,
        );

        // 30초 타임아웃 설정
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 30000);

        const response = await fetch(url, {
          method: "POST",
          headers: this.getHeaders(),
          body: JSON.stringify(payload),
          signal: controller.signal as any,
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
          throw new Error(`AI 서버 응답 오류 (Status: ${response.status})`);
        }

        return (await response.json()) as T;
      } catch (error) {
        lastError = error;
        Logger.warn(
          `[AiAdapter] ${serviceName} request failed (Attempt ${attempt}): ${error}`,
        );

        if (attempt < MAX_RETRIES) {
          // Exponential backoff: 1초, 2초 대기
          const delay = Math.pow(2, attempt - 1) * 1000;
          await new Promise((res) => setTimeout(res, delay));
        }
      }
    }

    // 3회 모두 실패 시 무조건 503 예외 발생 (Mock 데이터 반환 안 함)
    Logger.error(
      `[AiAdapter] Failed to connect to AI ${serviceName} server after ${MAX_RETRIES} attempts. Last error: ${lastError}`,
    );
    throw new AiServerError(
      `현재 우주 통신망이 불안정합니다. 잠시 후 다시 시도해주세요.`,
      "AI_SERVER_UNAVAILABLE",
      503,
    );
  }

  private async processBase64Image(
    imageUrl?: string,
    inputBase64?: string,
  ): Promise<string | undefined> {
    if (inputBase64) return inputBase64;
    if (!imageUrl) return undefined;

    const cleanPath = imageUrl.startsWith("/")
      ? imageUrl.substring(1)
      : imageUrl;
    const localFilePath = path.join(process.cwd(), cleanPath);

    if (!fs.existsSync(localFilePath)) return undefined;

    try {
      const rawBuffer = fs.readFileSync(localFilePath);
      const compressedBuffer = await compressImageBuffer(rawBuffer, {
        maxWidth: 512,
        maxHeight: 512,
        quality: 60,
        format: "jpeg",
      });
      Logger.info(
        `[AiAdapter] Compressed image for AI server (${rawBuffer.length} B -> ${compressedBuffer.length} B)`,
      );
      return `data:image/jpeg;base64,${compressedBuffer.toString("base64")}`;
    } catch (compressErr) {
      Logger.warn(`[AiAdapter] Image compression fallback: ${compressErr}`);
      return undefined;
    }
  }

  private resolveReportEndpoint(planetType: PlanetType | string): string {
    switch (planetType) {
      case "MEAL":
      case "NUTRITION":
        return "/v1/reports/diet";
      case "WATER":
      case "HYDRATION":
        return "/v1/reports/hydration";
      case "EXERCISE":
      case "LIFESTYLE":
        return "/v1/reports/lifestyle";
      case "EMOTION":
      case "MINDFULNESS":
        return "/v1/reports/mindfulness";
      case "RETROSPECT":
      case "RETROSPECTIVE":
        return "/v1/reports/retrospective";
      default:
        return "/v1/reports/diet";
    }
  }

  public async processChat(
    userId: number,
    userMessage: string,
    nickname?: string,
    history?: ChatTurn[],
  ): Promise<AiChatInternalResponse> {
    const payload: AiChatInternalPayload = {
      userId,
      userMessage,
      nickname,
      history,
    };
    return this.postJson<AiChatInternalResponse>(
      "/v1/chat/process",
      payload,
      "Chat",
    );
  }

  public async analyzeFoodVision(
    imageUrl?: string,
    mealType?: string,
    imageBase64Input?: string,
    yoloContext?: YoloContext,
  ): Promise<NormalizedVisionResult> {
    const imageBase64 = await this.processBase64Image(
      imageUrl,
      imageBase64Input,
    );
    const data = await this.postJson<AiVisionInternalResponse>(
      "/v1/vision/analyze-food",
      { imageUrl, imageBase64, mealType, yoloContext },
      "Vision",
    );

    // AI 서버는 음식명과 바운딩 박스만 담은 foods[]를 돌려준다. 리포트와
    // 마찬가지로 어댑터 안에서 백엔드 도메인 포맷(detectedFoods[])으로
    // 매핑해, 서비스 계층이 YOLO 결과와 동일하게 다루도록 한다.
    return {
      isIdentified: data.isIdentified,
      comment: data.comment,
      scanEngine: "VisionLLM",
      detectedFoods: (data.foods ?? []).map((f, idx) => ({
        boxId: idx,
        foodName: f.name,
        boundingBox: f.boundingBox,
        confidence: f.confidence,
      })),
    };
  }

  public async lookupNutrition(
    foodNames: string[],
  ): Promise<NutritionLookupResponse> {
    return this.postJson<NutritionLookupResponse>(
      "/v1/nutrition/lookup",
      { foodNames },
      "Nutrition Lookup",
    );
  }

  public async generatePlanetReport(
    planetType: PlanetType | string,
    payload: any,
  ): Promise<AiReportInternalResponse> {
    const endpoint = this.resolveReportEndpoint(planetType);
    const data = await this.postJson<any>(endpoint, payload, "Report");

    // 어댑터 내부에서 백엔드 도메인 포맷(AiReportInternalResponse)으로 명확히 매핑하여 반환
    return {
      title: data.title,
      markdown: data.markdown,
      summaryTitle: data.title || data.summaryTitle,
      findings: data.markdown || data.findings,
      nextActionChecks: data.nextActionChecks || [],
    };
  }
}

import type express from "express";
import jwt from "jsonwebtoken";
import config from "../../config";
import { UnauthorizedError } from "../../errors";

/**
 * JWT authentication middleware for TSOA controllers
 * @param request
 * @param securityName
 * @param scopes
 */
export function expressAuthentication(
  request: express.Request,
  securityName: string,
  scopes?: string[],
): Promise<any> {
  if (securityName === "jwt") {
    const authHeader = request.headers.authorization;

    if (authHeader && authHeader.startsWith("Bearer ")) {
      const token = authHeader.substring(7);

      // 개발 및 테스트용 Mock 토큰 예외 지원 (프로덕션 환경에서는 차단)
      if (
        (process.env.NODE_ENV !== "production" && token.startsWith("mock_")) ||
        process.env.NODE_ENV === "test"
      ) {
        const mockUser = {
          userId: 1,
          email: "mock_user@example.com",
          nickname: "우주탐험가",
        };
        (request as any).currentUser = mockUser;
        return Promise.resolve(mockUser);
      }

      try {
        const decoded = jwt.verify(token, config.jwtSecret) as {
          userId: number;
          email?: string;
        };
        const user = { userId: decoded.userId, email: decoded.email };
        (request as any).currentUser = user;
        return Promise.resolve(user);
      } catch (err) {
        return Promise.reject(
          new UnauthorizedError("만료되었거나 유효하지 않은 인증 토큰입니다."),
        );
      }
    }

    // 개발 및 테스트 보조 식별자 처리 (쿼리 파라미터 userId) - 프로덕션 환경에서는 차단
    const userIdQuery = request.query.userId;
    if (userIdQuery && process.env.NODE_ENV !== "production") {
      const user = { userId: Number(userIdQuery), nickname: "우주탐험가" };
      (request as any).currentUser = user;
      return Promise.resolve(user);
    }

    if (process.env.NODE_ENV === "test") {
      const mockUser = {
        userId: 1,
        email: "mock_user@example.com",
        nickname: "우주탐험가",
      };
      (request as any).currentUser = mockUser;
      return Promise.resolve(mockUser);
    }
  }

  return Promise.reject(
    new UnauthorizedError("인증 헤더(Bearer Token)가 누락되었습니다."),
  );
}

import type { Request, Response, NextFunction } from "express";
import { AppError } from "../../errors";
import Logger from "../../loaders/logger";

/**
 * Global Error Handling Middleware for Express & TSOA
 * @param err
 * @param req
 * @param res
 * @param next
 */
export function globalErrorHandler(
  err: any,
  req: Request,
  res: Response,
  next: NextFunction,
): void {
  if (res.headersSent) {
    return next(err);
  }

  // 1. 커스텀 애플리케이션 예외 (AppError)
  if (err instanceof AppError) {
    Logger.warn(
      `[AppError] ${req.method} ${req.path} - ${err.code} (${err.status}): ${err.message}`,
    );
    res.status(err.status).json({
      code: err.code,
      message: err.message,
      status: err.status,
      ...(typeof err.details === "object" && err.details !== null
        ? err.details
        : {}),
    });
    return;
  }

  // 2. TSOA Request Body / Query Validation Error
  if (err.name === "ValidateError" || err.status === 400) {
    Logger.warn(`[ValidationError] ${req.method} ${req.path} - ${err.message}`);
    res.status(400).json({
      code: "VALIDATION_ERROR",
      message: "요청 데이터 유효성 검증에 실패하였습니다.",
      status: 400,
      details: err.fields || err.message,
    });
    return;
  }

  // 3. 처리되지 않은 500 Internal Server Error (스택 트레이스는 로거로 기록 후 은닉)
  console.error("🔥 [Unhandled Error Detail]:", err);
  Logger.error(
    `[UnhandledError] ${req.method} ${req.path} - ${err.stack || err.message}`,
  );
  res.status(500).json({
    code: "INTERNAL_SERVER_ERROR",
    message: "서버 내부 오류가 발생하였습니다. 잠시 후 다시 시도해주세요.",
    status: 500,
  });
}

import { Route, Post, Delete, Body, Security, Request, Tags } from "tsoa";
import { Service, Container } from "typedi";
import AuthService from "../../services/authService";
import type { AuthenticatedRequest } from "../../interfaces/express";
import { ApiResponse } from "../../dto";
import { BaseController } from "./BaseController";
import type {
  UserSignUpRequest,
  UserLoginRequest,
  UserLoginResponse,
  TokenRefreshRequest,
  TokenRefreshResponse,
  UserWithdrawRequest,
  UserWithdrawResponse,
  SocialLoginRequest,
} from "../../dto";

@Service()
@Tags("1. Auth - 회원 인증 및 소셜 로그인")
@Route("auth")
export class AuthController extends BaseController {
  private authService = Container.get(AuthService);

  /**
   * 이메일과 비밀번호 기반으로 신규 회원을 등록합니다.
   * @param requestBody
   * @summary 일반 회원가입
   */
  @Post("signup")
  public async signUp(
    @Body() requestBody: UserSignUpRequest,
  ): Promise<ApiResponse<UserLoginResponse>> {
    const result = await this.authService.signUp(requestBody);
    return this.success(result, "회원가입이 성공적으로 완료되었습니다.", 201);
  }

  /**
   * [3.6] 로그인 API
   * @param requestBody
   */
  @Post("login")
  public async login(
    @Body() requestBody: UserLoginRequest,
  ): Promise<ApiResponse<UserLoginResponse>> {
    const result = await this.authService.login(requestBody);
    return this.success(result, "로그인이 성공적으로 완료되었습니다.");
  }

  /**
   * [3.6] 구글 / 카카오 / 애플 소셜 로그인 API
   * @param requestBody
   */
  @Post("social-login")
  public async socialLogin(
    @Body() requestBody: SocialLoginRequest,
  ): Promise<ApiResponse<UserLoginResponse>> {
    const result = await this.authService.socialLogin(requestBody);
    return this.success(result, "소셜 로그인이 성공적으로 완료되었습니다.");
  }

  /**
   * [3.6] 토큰 자동 갱신 API
   * @param requestBody
   */
  @Post("refresh")
  public async refresh(
    @Body() requestBody: TokenRefreshRequest,
  ): Promise<ApiResponse<TokenRefreshResponse>> {
    const result = await this.authService.refresh(requestBody);
    return this.success(result, "토큰이 성공적으로 갱신되었습니다.");
  }

  /**
   * [3.6] 회원 탈퇴 API
   * @param request
   * @param requestBody
   */
  @Post("withdraw")
  @Security("jwt")
  public async withdrawPost(
    @Request() request: AuthenticatedRequest,
    @Body() requestBody?: UserWithdrawRequest,
  ): Promise<ApiResponse<UserWithdrawResponse>> {
    const result = await this.authService.withdraw(
      this.getUserId(request),
      requestBody,
    );
    return this.success(result, "회원 탈퇴가 완료되었습니다.");
  }

  @Delete("withdraw")
  @Security("jwt")
  public async withdraw(
    @Request() request: AuthenticatedRequest,
    @Body() requestBody?: UserWithdrawRequest,
  ): Promise<ApiResponse<UserWithdrawResponse>> {
    const result = await this.authService.withdraw(
      this.getUserId(request),
      requestBody,
    );
    return this.success(result, "회원 탈퇴가 완료되었습니다.");
  }
}

import { Controller } from "tsoa";
import { ApiResponse } from "../../dto";
import {
  getAuthenticatedUserId,
  type AuthenticatedRequest,
} from "../../interfaces/express";

export abstract class BaseController extends Controller {
  /**
   * 성공 응답 객체 생성 및 HTTP 상태 코드 설정 헬퍼
   * @param data
   * @param message
   * @param statusCode
   */
  protected success<T>(
    data: T,
    message?: string,
    statusCode: number = 200,
  ): ApiResponse<T> {
    if (statusCode !== 200) {
      this.setStatus(statusCode);
    }
    return ApiResponse.success(data, message, statusCode);
  }

  /**
   * 인증된 요청 객체에서 유저 ID 추출 헬퍼
   * @param request
   */
  protected getUserId(request: AuthenticatedRequest): number {
    return getAuthenticatedUserId(request);
  }
}

import { Route, Post, Delete, Body, Path, Security, Request, Tags } from "tsoa";
import { Service, Container } from "typedi";
import ChatService from "../../services/chatService";
import type { AuthenticatedRequest } from "../../interfaces/express";
import { ApiResponse } from "../../dto";
import { BaseController } from "./BaseController";
import { ChatMessageApiRequest } from "../../dto";

@Service()
@Tags("5. TammyChat - AI 타미 심리 공감 대화")
@Route("chat")
export class ChatController extends BaseController {
  private chatService = Container.get(ChatService);

  /**
   * AI 버추얼 펫 타미(TAMMY)와 실시간 심리 공감 대화를 나누고, 모션 태그 응답 수령 및 장기 기억 캡슐을 생성합니다.
   * @param request
   * @param body
   * @summary AI 타미 심리 공감 메시지 전송
   */
  @Post("message")
  @Security("jwt")
  public async sendMessage(
    @Request() request: AuthenticatedRequest,
    @Body() body: ChatMessageApiRequest,
  ): Promise<ApiResponse<any>> {
    const result = await this.chatService.processChat(
      this.getUserId(request),
      body.messageText,
    );
    return this.success(result, "메시지가 성공적으로 전달되었습니다.");
  }

  /**
   * [3.4] 대화 메시지 소프트 삭제 API
   * @param request
   * @param messageId
   */
  @Delete("messages/{messageId}")
  @Security("jwt")
  public async deleteMessage(
    @Request() request: AuthenticatedRequest,
    @Path() messageId: string,
  ): Promise<ApiResponse<null>> {
    await this.chatService.deleteMessage(messageId);
    return this.success(null as any, "메시지가 성공적으로 삭제되었습니다.");
  }

  /**
   * [3.4] 대화 메시지 삭제 취소 (Undo) API
   * @param request
   * @param messageId
   */
  @Post("messages/{messageId}/undo")
  @Security("jwt")
  public async undoDeleteMessage(
    @Request() request: AuthenticatedRequest,
    @Path() messageId: string,
  ): Promise<ApiResponse<null>> {
    await this.chatService.undoDeleteMessage(messageId);
    return this.success(null as any, "메시지 삭제가 취소되었습니다.");
  }
}

import {
  Route,
  Post,
  Body,
  Security,
  Request,
  UploadedFile,
  FormField,
  Tags,
} from "tsoa";
import { Service, Container } from "typedi";
import FoodService from "../../services/foodService";
import { MealType } from "../../interfaces/enums";
import type { AuthenticatedRequest } from "../../interfaces/express";
import { ApiResponse } from "../../dto";
import { BaseController } from "./BaseController";
import {
  FoodLogConfirmRequest,
  FoodVisionScanResponse,
  FoodLogConfirmResponse,
} from "../../dto";

@Service()
@Tags("4. FoodVision - 식단 스캔 & 영양성분 기록")
@Route("")
export class FoodController extends BaseController {
  private foodService = Container.get(FoodService);

  /**
   * 촬영하거나 선택한 식단 사진 이미지 파일(multipart/form-data)을 업로드하고 AI 비전 모델로 5대 영양 성분을 스캔 분석합니다.
   * @param file
   * @param mealType
   * @summary 식단 사진 파일 업로드 & AI 비전 분석 스캔
   */
  @Post("food-vision/scan")
  @Security("jwt")
  public async scanFoodVision(
    @UploadedFile("file") file: Express.Multer.File,
    @FormField("mealType") mealType?: MealType,
  ): Promise<ApiResponse<FoodVisionScanResponse>> {
    const data = await this.foodService.uploadAndAnalyzeFoodVision(
      file,
      mealType,
    );
    return this.success(data as FoodVisionScanResponse);
  }

  /**
   * [추가] 외부 AI 서버를 통한 음식 사진 객체 검출 API
   * @param file
   * @summary 외부 AI 서버 기반 식단 검출 및 매칭
   */
  @Post("food-vision/ai-detect")
  @Security("jwt")
  public async detectFoodFromAiServer(
    @UploadedFile("file") file: Express.Multer.File,
  ): Promise<ApiResponse<any>> {
    const data = await this.foodService.detectFoodViaExternalAi(file);
    return this.success(data);
  }

  /**
   * [3.2] Food Log 확정 저장 API
   * @param request
   * @param body
   */
  @Post("food-log/confirm")
  @Security("jwt")
  public async confirmFoodLog(
    @Request() request: AuthenticatedRequest,
    @Body() body: FoodLogConfirmRequest,
  ): Promise<ApiResponse<FoodLogConfirmResponse>> {
    const res = await this.foodService.logMeal(this.getUserId(request), {
      mealType: body.mealType as MealType,
      imageId: body.imageId,
      foods: body.foods,
      comment: body.comment,
    });
    const data: FoodLogConfirmResponse = {
      mealId: res.mealId,
      earnedFuel: res.earnedFuel,
      totalCalories: res.totalCalories,
    };
    return this.success(data);
  }
}

import { Route, Post, Body, Security, Request, Tags } from "tsoa";
import { Service, Container } from "typedi";
import NotificationService from "../../services/notificationService";
import type { AuthenticatedRequest } from "../../interfaces/express";
import { ApiResponse } from "../../dto";
import { BaseController } from "./BaseController";
import type {
  PushTokenRegisterRequest,
  PushTokenRegisterResponse,
} from "../../dto";

@Service()
@Tags("8. Notification - 푸시 알림 및 디바이스 토큰")
@Route("notifications")
export class NotificationController extends BaseController {
  private notificationService = Container.get(NotificationService);

  /**
   * 모바일 앱 디바이스의 FCM 푸시 알림 토큰을 등록하여 탐사 결과 알림을 발송받습니다.
   * @param request
   * @param requestBody
   * @summary FCM 디바이스 푸시 토큰 등록
   */
  @Post("push-token")
  @Security("jwt")
  public async registerPushToken(
    @Request() request: AuthenticatedRequest,
    @Body() requestBody: PushTokenRegisterRequest,
  ): Promise<ApiResponse<PushTokenRegisterResponse>> {
    const result = await this.notificationService.registerPushToken(
      this.getUserId(request),
      requestBody,
    );
    return this.success(result, "푸시 토큰 등록이 완료되었습니다.");
  }
}

import { Route, Post, Body, Security, Request, Tags } from "tsoa";
import { Service, Container } from "typedi";
import QuickLogService from "../../services/quickLogService";
import type { AuthenticatedRequest } from "../../interfaces/express";
import {
  QuickLogApiRequest,
  QuickLogApiResponse,
  ApiResponse,
} from "../../dto";
import { BaseController } from "./BaseController";

@Service()
@Tags("3. QuickLog - 1-Tap 웰니스 퀵기록")
@Route("quick-log")
export class QuickLogController extends BaseController {
  private quickLogService = Container.get(QuickLogService);

  /**
   * 수분 섭취, 기분/감정, 일기 작성, 운동 완료 등 데일리 웰니스 항목을 1-Tap으로 원터치 기록하고 우주 연료(Fuel)를 적립합니다.
   * @param request
   * @param requestBody
   * @summary 1-Tap 웰니스 퀵기록 생성
   */
  @Post("")
  @Security("jwt")
  public async createQuickLog(
    @Request() request: AuthenticatedRequest,
    @Body() requestBody: QuickLogApiRequest,
  ): Promise<ApiResponse<QuickLogApiResponse>> {
    if (
      requestBody.category === "WATER" &&
      (requestBody.amount === undefined || requestBody.amount < 0)
    ) {
      this.setStatus(400);
      return ApiResponse.error(
        "수분 섭취량은 0 이상이어야 합니다.",
        400,
      ) as any;
    }
    const result = await this.quickLogService.createQuickLog(
      this.getUserId(request),
      requestBody,
    );
    return this.success(
      result.data,
      "퀵기록이 성공적으로 등록되었습니다.",
      201,
    );
  }
}

import { Route, Post, Get, Path, Body, Security, Request, Tags } from "tsoa";
import { Service, Container } from "typedi";
import TravelService from "../../services/travelService";
import { reportQueue } from "../../utils/asyncQueue";
import type { AuthenticatedRequest } from "../../interfaces/express";
import { ApiResponse } from "../../dto";
import { BaseController } from "./BaseController";
import {
  PlanetTravelStartApiRequest,
  PlanetTravelStartApiResponse,
  TravelStateInfoResponse,
  DashboardSummaryInfo,
  TravelResultDetailInfo,
} from "../../dto";
import { toTravelResultDetailInfo } from "../../mappers";

@Service()
@Tags("6. PlanetTravel - 별여행 게이미피케이션 탐사 & 진단서")
@Route("")
export class TravelController extends BaseController {
  private travelService = Container.get(TravelService);

  /**
   * 보유한 우주 연료(Fuel)를 소모하여 선택한 행성으로 별여행을 출발하고, AI 탐사 결과(travelResult) 진단서를 실시간 동기 생성합니다.
   * @param request
   * @param body
   * @summary 별여행 탐사 출발 및 AI 탐사결과 생성
   */
  @Post("planet-travel/start")
  @Security("jwt")
  public async startPlanetTravel(
    @Request() request: AuthenticatedRequest,
    @Body() body: PlanetTravelStartApiRequest,
  ): Promise<ApiResponse<PlanetTravelStartApiResponse>> {
    const result = await this.travelService.startPlanetTravel(
      this.getUserId(request),
      body,
    );
    return this.success(result, "별여행 탐사가 성공적으로 시작되었습니다.");
  }

  /**
   * 우주여행 현황 조회
   * @param request
   * @summary 우주여행 현황 조회
   */
  @Get("planet-travel/state")
  @Security("jwt")
  public async getTravelState(
    @Request() request: AuthenticatedRequest,
  ): Promise<ApiResponse<TravelStateInfoResponse>> {
    const result = await this.travelService.getTravelState(
      this.getUserId(request),
    );
    return this.success(result, "우주여행 현황 조회가 완료되었습니다.");
  }

  /**
   * 행성 탐사 완료 후 생성된 AI 별여행 탐사 결과 진단서(travelResult)의 상세 보고서 내용을 조회합니다.
   * @param travelResultId
   * @param request
   * @summary AI 별여행 탐사 결과 진단서 상세 조회
   */
  @Get("travel-results/{travelResultId}")
  @Security("jwt")
  public async getTravelResult(
    @Path() travelResultId: string,
    @Request() request: AuthenticatedRequest,
  ): Promise<ApiResponse<TravelResultDetailInfo>> {
    const result = await this.travelService.getTravelResultById(
      travelResultId,
      this.getUserId(request),
    );
    const data = toTravelResultDetailInfo(result);
    return this.success(data, "진단서 상세 조회가 완료되었습니다.");
  }

  /**
   * 주간 칼로리 섭취 추이 및 3대 영양소 밸런스 비율 통계 대시보드를 조회합니다.
   * @param request
   * @summary 웰니스 종합 대시보드 통계 조회
   */
  @Get("dashboard/summary")
  @Security("jwt")
  public async getDashboardSummary(
    @Request() request: AuthenticatedRequest,
  ): Promise<ApiResponse<DashboardSummaryInfo>> {
    const dashboard = await this.travelService.getDashboard(
      this.getUserId(request),
      "WEEKLY",
    );
    return this.success(dashboard, "대시보드 통계 조회가 완료되었습니다.");
  }

  /**
   * 비동기 리포트 작업의 진행 상황을 Server-Sent Events(SSE)로 실시간 푸시합니다.
   * @param jobId
   * @param request
   * @summary 비동기 리포트 생성 실시간 상태 조회 (SSE)
   */
  @Get("reports/sse/{jobId}")
  public async getReportSSE(
    @Path() jobId: string,
    @Request() request: any,
  ): Promise<void> {
    const res = request.res;
    if (!res) throw new Error("Express Response 객체를 찾을 수 없습니다.");

    res.writeHead(200, {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache",
      Connection: "keep-alive",
    });
    res.write(
      `data: ${JSON.stringify({ status: "CONNECTED", message: "SSE 연결 성공" })}\n\n`,
    );

    const onUpdate = (job: any) => {
      if (job.id === jobId) {
        res.write(`data: ${JSON.stringify(job)}\n\n`);
        if (job.status === "COMPLETED" || job.status === "FAILED") {
          res.end();
          reportQueue.off("job_updated", onUpdate);
        }
      }
    };

    reportQueue.on("job_updated", onUpdate);

    // 즉시 현재 상태 전송
    const currentJob = reportQueue.getJob(jobId);
    if (currentJob) {
      res.write(`data: ${JSON.stringify(currentJob)}\n\n`);
      if (currentJob.status === "COMPLETED" || currentJob.status === "FAILED") {
        res.end();
        reportQueue.off("job_updated", onUpdate);
        return;
      }
    }

    // 클라이언트 연결 종료 시 리스너 해제
    request.on("close", () => {
      reportQueue.off("job_updated", onUpdate);
    });

    // SSE 연결 유지를 위해 Promise를 해결하지 않고 대기
    return new Promise(() => {});
  }
}

