      where: {
        user_id_device_token: {
          user_id: userId,
          device_token: deviceToken,
        },
      },
      update: {
        device_type: deviceType,
        is_active: true,
        updated_at: new Date(),
      },
      create: {
        user_id: userId,
        device_token: deviceToken,
        device_type: deviceType,
        is_active: true,
      },
    });
  }

  public async findActivePushTokens(userId: number) {
    return this.findMany({
      user_id: userId,
      is_active: true,
    });
  }
}

