import Logger from "../loaders/logger";
import { EventEmitter } from "events";

export type JobStatus = "PENDING" | "IN_PROGRESS" | "COMPLETED" | "FAILED";

export interface Job<T = any> {
  id: string;
  status: JobStatus;
  progressPercent: number;
  result?: T;
  error?: string;
  createdAt: Date;
  updatedAt: Date;
}

export class AsyncQueue<T = any> extends EventEmitter {
  private jobs: Map<string, Job<T>> = new Map();
  private queue: Array<{ id: string; taskFn: () => Promise<T> }> = [];
  private activeCount = 0;
  private concurrency: number;

  constructor(concurrency = 2) {
    super();
    this.concurrency = concurrency;
  }

  public enqueue(jobId: string, taskFn: () => Promise<T>): string {
    const job: Job<T> = {
      id: jobId,
      status: "PENDING",
      progressPercent: 0,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    this.jobs.set(jobId, job);
    this.queue.push({ id: jobId, taskFn });
    this.emit("job_updated", job);
    this.processNext();

    return jobId;
  }

  public getJob(jobId: string): Job<T> | undefined {
    return this.jobs.get(jobId);
  }

  private async processNext() {
    if (this.activeCount >= this.concurrency || this.queue.length === 0) {
      return;
    }

    const item = this.queue.shift();
    if (!item) return;

    this.activeCount++;
    const job = this.jobs.get(item.id);
    if (job) {
      job.status = "IN_PROGRESS";
      job.progressPercent = 30;
      job.updatedAt = new Date();
      this.emit("job_updated", job);
    }

    try {
      Logger.info(`[AsyncQueue] Processing job ${item.id}`);
      const result = await item.taskFn();
      if (job) {
        job.status = "COMPLETED";
        job.progressPercent = 100;
        job.result = result;
        job.updatedAt = new Date();
        this.emit("job_updated", job);
      }
      Logger.info(`[AsyncQueue] Successfully completed job ${item.id}`);
    } catch (err: any) {
      if (job) {
        job.status = "FAILED";
        job.error = err?.message || String(err);
        job.updatedAt = new Date();
        this.emit("job_updated", job);
      }
      Logger.error(`[AsyncQueue] Job ${item.id} failed: ${err}`);
    } finally {
      this.activeCount--;
      this.processNext().catch((e) =>
        Logger.error(`[AsyncQueue] processNext error: ${e}`),
      );
    }
  }
}

export const reportQueue = new AsyncQueue();

/**
 * 음식 수식어/접두어 사전 (Modifier Dictionary)
 */
export const FOOD_MODIFIER_DICTIONARY = new Set([
  "고추",
  "매운",
  "치즈",
  "국물",
  "로제",
  "짜장",
  "수제",
  "마라",
  "크림",
  "불",
  "대파",
  "직화",
  "바삭한",
  "얼큰한",
  "달콤한",
  "훈제",
  "양념",
  "간장",
  "후라이드",
  "양념반",
]);

/**
 * 수량/단위 정규식 패턴 (Quantity Pattern)
 */
export const QUANTITY_PATTERN =
  /^(\d+(\.\d+)?)(인분|g|gram|개|그릇|공기|조각|줄|잔|캔|병)$/i;

/**
 * 토큰 분석 결과 구조체
 */
export interface FoodTokenAnalysisResult {
  rawName: string;
  modifiers: string[];
  quantity?: string;
  coreFoodName: string;
  normalizedName: string;
  tokens: string[];
}

/**
 * 음식 원본 이름을 토큰화하고 정규화된 키워드를 추출합니다.
 * 예: '매운 수제 치즈 닭갈비 2인분' ➔ modifiers: ['매운', '수제', '치즈'], quantity: '2인분', coreFoodName: '닭갈비'
 * @param rawName
 */
export function tokenizeFoodName(rawName: string): FoodTokenAnalysisResult {
  if (!rawName || !rawName.trim()) {
    return {
      rawName: "",
      modifiers: [],
      coreFoodName: "",
      normalizedName: "",
      tokens: [],
    };
  }

  const cleanRaw = rawName.trim();
  const rawTokens = cleanRaw.split(/\s+/);

  const modifiers: string[] = [];
  let quantity: string | undefined = undefined;
  const coreTokens: string[] = [];

  for (const token of rawTokens) {
    if (QUANTITY_PATTERN.test(token)) {
      quantity = token;
    } else if (FOOD_MODIFIER_DICTIONARY.has(token)) {
      modifiers.push(token);
    } else {
      coreTokens.push(token);
    }
  }

  let coreFoodName = coreTokens.join(" ");
  if (!coreFoodName) {
    coreFoodName = rawTokens.filter((t) => !QUANTITY_PATTERN.test(t)).join(" ");
  }

  return {
    rawName: cleanRaw,
    modifiers,
    quantity,
    coreFoodName,
    normalizedName: coreFoodName || cleanRaw,
    tokens: rawTokens,
  };
}

/**
 * 음식명 정제 시 제거할 대표 수식어/접두어 목록
 */
export const FOOD_MODIFIER_KEYWORDS = [
  "고추",
  "매운",
  "치즈",
  "국물",
  "로제",
  "짜장",
  "수제",
  "마라",
  "크림",
  "불",
  "대파",
] as const;

/**
 * 음식 원본 이름에서 수식어를 제거하여 검색용 키워드를 정제합니다.
 * 예: '고추떡볶이' ➔ '떡볶이', '치즈돈까스' ➔ '돈까스'
 * @param rawName
 */
export function cleanFoodKeyword(rawName: string): string {
  if (!rawName) return "";
  const pattern = new RegExp(`(${FOOD_MODIFIER_KEYWORDS.join("|")})`, "g");
  return rawName.replace(pattern, "").trim();
}

